#include <string>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int longestPalindrome(string s) {
        unordered_map<char, int> count;
        for (char c : s) count[c]++;
        int length = 0, odd = 0;
        for (auto& p : count) {
            length += p.second / 2 * 2;
            if (p.second % 2) odd = 1;
        }
        return length + odd;
    }
};
